import AppKit
import ApplicationServices
import Carbon.HIToolbox
import CharlCore
import CharlPlatform
import CoreGraphics
import Foundation

/// NSPasteboard changeCount 轮询实现。
/// 尊重密码管理器等写入的 Concealed/Transient/AutoGenerated 标记，不记录敏感内容。
public final class PasteboardMonitor: ClipboardService {
    private let pasteboard = NSPasteboard.general
    private let storage: StorageService
    private var timer: Timer?
    private var lastChangeCount: Int
    private var pendingChangeCount: Int?
    private var pendingRetries = 0
    private var onChange: ((ClipboardItem) -> Void)?

    private static let ignoredTypes: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
    ]

    private static let utf8Type = NSPasteboard.PasteboardType("public.utf8-plain-text")

    public init(storage: StorageService) {
        self.storage = storage
        lastChangeCount = pasteboard.changeCount
    }

    public func startMonitoring(onChange: @escaping (ClipboardItem) -> Void) {
        self.onChange = onChange
        lastChangeCount = pasteboard.changeCount
        let timer = Timer(timeInterval: AppConfig.clipboardPollInterval, repeats: true) { [weak self] _ in
            self?.tick()
        }
        RunLoop.main.add(timer, forMode: .common)
        self.timer = timer
        Log.clipboard.notice("monitoring started")
    }

    public func stopMonitoring() {
        timer?.invalidate()
        timer = nil
    }

    public func copy(_ item: ClipboardItem) {
        pasteboard.clearContents()
        switch item.kind {
        case .text:
            pasteboard.setString(item.text ?? "", forType: .string)
        case .image:
            if let data = imageData(for: item), let image = NSImage(data: data) {
                pasteboard.writeObjects([image])
            }
        }
        lastChangeCount = pasteboard.changeCount
        pendingChangeCount = nil
        Log.clipboard.notice("copied back \(item.kind.rawValue, privacy: .public) item")
    }

    public func imageData(for item: ClipboardItem) -> Data? {
        guard let file = item.imageFile else { return nil }
        return try? storage.read(file)
    }

    public func thumbnailData(for item: ClipboardItem) -> Data? {
        guard let file = item.imageFile else { return nil }
        return try? storage.read(Self.thumbnailPath(for: file))
    }

    public func deleteImageFiles(for item: ClipboardItem) {
        guard let file = item.imageFile else { return }
        try? storage.remove(file)
        try? storage.remove(Self.thumbnailPath(for: file))
    }

    public var canAutoPaste: Bool {
        AXIsProcessTrusted()
    }

    @discardableResult
    public func requestAutoPastePermission() -> Bool {
        let options = [kAXTrustedCheckOptionPrompt.takeUnretainedValue() as String: true] as CFDictionary
        return AXIsProcessTrustedWithOptions(options)
    }

    public func sendPasteKeystroke() {
        guard canAutoPaste else {
            Log.clipboard.notice("autoPaste skipped: accessibility not trusted")
            return
        }
        let source = CGEventSource(stateID: .hidSystemState)
        let down = CGEvent(keyboardEventSource: source, virtualKey: CGKeyCode(kVK_ANSI_V), keyDown: true)
        down?.flags = .maskCommand
        let up = CGEvent(keyboardEventSource: source, virtualKey: CGKeyCode(kVK_ANSI_V), keyDown: false)
        up?.flags = .maskCommand
        down?.post(tap: .cghidEventTap)
        up?.post(tap: .cghidEventTap)
        Log.clipboard.notice("autoPaste keystroke sent")
    }

    private static func thumbnailPath(for file: String) -> String {
        let base = file.hasSuffix(".png") ? String(file.dropLast(4)) : file
        return base + ".thumb.png"
    }

    private func tick() {
        let changeCount = pasteboard.changeCount
        if let pending = pendingChangeCount, changeCount == pending {
            pendingRetries += 1
            if pendingRetries > 6 {
                pendingChangeCount = nil
                lastChangeCount = changeCount
                return
            }
        } else if changeCount != lastChangeCount {
            pendingChangeCount = changeCount
            pendingRetries = 0
            Log.clipboard.notice("change detected cc=\(changeCount) types=\(self.pasteboard.types?.map(\.rawValue).joined(separator: ",") ?? "nil", privacy: .public)")
        } else {
            return
        }

        guard let types = pasteboard.types else {
            lastChangeCount = changeCount
            pendingChangeCount = nil
            return
        }
        if !Set(types.map(\.rawValue)).isDisjoint(with: Self.ignoredTypes) {
            Log.clipboard.notice("skipped concealed/transient pasteboard content")
            lastChangeCount = changeCount
            pendingChangeCount = nil
            return
        }

        let frontmost = NSWorkspace.shared.frontmostApplication
        let sourceApp = frontmost?.localizedName
        let sourceBundleID = frontmost?.bundleIdentifier

        if types.contains(.string) || types.contains(Self.utf8Type) {
            // 优先 UTF-8 类型：legacy NSStringPboardType 对非 ASCII 内容可能是非 UTF8 编码
            let text = pasteboard.string(forType: Self.utf8Type) ?? pasteboard.string(forType: .string)
            if let text, !text.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
                let item = ClipboardItem(kind: .text, text: text, byteSize: text.utf8.count, sourceApp: sourceApp, sourceBundleID: sourceBundleID)
                Log.clipboard.notice("captured text \(text.utf8.count) bytes from \(sourceApp ?? "?", privacy: .public)")
                lastChangeCount = changeCount
                pendingChangeCount = nil
                onChange?(item)
            }
            // 类型在但内容暂不可读（延迟提交/隐私门）：保留 pending 下轮重试
            return
        }

        // 只在主线程取原始数据（不解码），解码/编码/缩略图/落盘放到后台，避免大图造成主线程卡顿。
        let raw = pasteboard.data(forType: .png)
            ?? pasteboard.data(forType: .tiff)
            ?? pasteboard.data(forType: NSPasteboard.PasteboardType("public.jpeg"))
        guard let raw else { return }
        lastChangeCount = changeCount
        pendingChangeCount = nil
        DispatchQueue.global(qos: .userInitiated).async { [weak self] in
            guard let self else { return }
            guard let rep = NSBitmapImageRep(data: raw)
                ?? NSImage(data: raw)?.tiffRepresentation.flatMap({ NSBitmapImageRep(data: $0) }) else { return }
            guard let png = rep.representation(using: .png, properties: [:]) else { return }
            guard png.count <= AppConfig.maxImageBytes else {
                Log.clipboard.notice("skipped oversized image \(png.count) bytes")
                return
            }
            let id = UUID()
            let file = "clipboard/images/\(id.uuidString).png"
            do {
                try self.storage.write(png, to: file)
                try self.storage.write(Self.thumbnail(from: rep), to: Self.thumbnailPath(for: file))
            } catch {
                Log.clipboard.error("image persist failed: \(error.localizedDescription, privacy: .public)")
                return
            }
            let item = ClipboardItem(
                id: id,
                kind: .image,
                imageFile: file,
                imageWidth: rep.pixelsWide,
                imageHeight: rep.pixelsHigh,
                byteSize: png.count,
                sourceApp: sourceApp,
                sourceBundleID: sourceBundleID
            )
            Log.clipboard.notice("captured image \(rep.pixelsWide)x\(rep.pixelsHigh) from \(sourceApp ?? "?", privacy: .public)")
            DispatchQueue.main.async { self.onChange?(item) }
        }
    }

    private static func thumbnail(from rep: NSBitmapImageRep) -> Data {
        let longest = max(rep.pixelsWide, rep.pixelsHigh)
        let scale = min(1, AppConfig.thumbnailMaxPixel / Double(longest))
        let width = max(1, Int(Double(rep.pixelsWide) * scale))
        let height = max(1, Int(Double(rep.pixelsHigh) * scale))
        guard let thumb = NSBitmapImageRep(
            bitmapDataPlanes: nil,
            pixelsWide: width,
            pixelsHigh: height,
            bitsPerSample: 8,
            samplesPerPixel: 4,
            hasAlpha: true,
            isPlanar: false,
            colorSpaceName: .deviceRGB,
            bytesPerRow: 0,
            bitsPerPixel: 0
        ) else { return Data() }
        NSGraphicsContext.saveGraphicsState()
        NSGraphicsContext.current = NSGraphicsContext(bitmapImageRep: thumb)
        NSGraphicsContext.current?.imageInterpolation = .high
        rep.draw(in: NSRect(x: 0, y: 0, width: width, height: height))
        NSGraphicsContext.restoreGraphicsState()
        return thumb.representation(using: .png, properties: [:]) ?? Data()
    }
}